 select count(*) into present from public.mindex_bible_translations where id in('8bb0463f-eebf-459a-b5be-2f6d43b38ad6'::uuid,'1df71e15-ed1b-4e1b-acc2-cf1192d66980'::uuid,'f98f4683-e3d5-4829-82aa-8e2e8b8d2adf'::uuid,'76f03b12-a0dd-44f5-8ac2-c5e99ae38618'::uuid,'ead292a9-0330-4f7b-952b-567583ac269f'::uuid,'577799c0-d75b-4ea2-b9ee-ef704557b175'::uuid,'559ce8cc-7af7-4ba3-bc09-b09925d8c440'::uuid,'1bbf8fc6-be14-4bfc-b799-715dd7682e49'::uuid);
